using System;using System.IO;using System.Linq;using System.Collections.Generic;using Musikbox;
class LatestImportTests {
 static int count;static void Check(bool b,string text){if(!b)throw new Exception(text);count++;Console.WriteLine("OK "+text);}
 static void Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);string input=Path.GetFullPath(args[1]);var before=File.ReadAllBytes(input);var old=new Project{ReencodeMp3=true,Mp3Bitrate=192,FfmpegExecutable="/usr/bin/ffmpeg"};for(int i=0;i<5;i++)old.Folders.Add(new BoxFolder{Name=(30+i).ToString("D3")+" Country",Theme="Country",Songs=new List<Song>{new Song{Source=input,Artist="Alt",Title="Bisher "+i,Album="Country"}}});var snapshot=Storage.Bytes(old);
  string incoming=Path.Combine(root,"Einzeltitel");Directory.CreateDirectory(incoming);string a=Path.Combine(incoming,"A.mp3"),b=Path.Combine(incoming,"B.mp3");MediaMetadata.WriteCopy(new Song{Source=input,Artist="Glen Campbell",Title="Sunflower"},"Neue Titel",a,()=>{});MediaMetadata.WriteCopy(new Song{Source=input,Artist="Lainey Wilson",Title="Wildflowers and Wild Horses"},"Neue Titel",b,()=>{});
  foreach(var mode in new[]{FolderImportMode.PreserveStructure,FolderImportMode.ByAlbumTags}){var r=DropImport.Read(old,new[]{a,b},3,()=>{},mode);Check(r.FilesAdded==2&&r.Project.Folders.SelectMany(f=>f.Songs).Count()==2,"Fünf bisherige Country-Ordner durch genau zwei neue Titel ersetzt · "+mode);Check(!r.Project.Folders.Any(f=>f.Theme=="Country")&&r.Project.Folders.SelectMany(f=>f.Songs).All(s=>s.Title!="Bisher"),"Keine alten Ordner im neuen Ergebnis · "+mode);Check(r.Project.ReencodeMp3&&r.Project.Mp3Bitrate==192&&r.Project.FfmpegExecutable==old.FfmpegExecutable,"Audioeinstellungen bleiben erhalten · "+mode);Check(r.Warnings.Count==0&&r.Project.Folders[0].Name.StartsWith("000 "),"Keine Kollision mit alten Ordnernummern und kein veralteter Nummerierungshinweis · "+mode);Check(Storage.Bytes(old).SequenceEqual(snapshot),"Eingangsprojekt bis zur erfolgreichen Übernahme unverändert · "+mode);}
  var first=DropImport.Read(old,new[]{a,b},-1,()=>{});var again=DropImport.Read(first.Project,new[]{a},-1,()=>{});Check(again.FilesAdded==1&&again.Project.Folders.SelectMany(f=>f.Songs).Single().Source==a,"Erneuter Import derselben Quelle zeigt genau diesen letzten Titel");
  var duplicate=DropImport.Read(old,new[]{a,a,b},-1,()=>{});Check(duplicate.FilesAdded==2&&duplicate.Skipped==1,"Dubletten werden innerhalb des neuen Imports weiterhin übersprungen");
  var overlap=DropImport.Read(old,new[]{incoming,a},-1,()=>{});Check(overlap.FilesAdded==2&&overlap.Project.Folders.SelectMany(f=>f.Songs).Count()==2,"Überlappende Ordner-/Dateiauswahl enthält keine doppelten Titel");
  var invalid=DropImport.Read(old,new[]{Path.Combine(root,"fehlt.mp3")},-1,()=>{});Check(invalid.FilesAdded==0&&Object.ReferenceEquals(invalid.Project,old),"Ungültiger Import ersetzt die bestehende Bibliothek nicht");var empty=Path.Combine(root,"Leer");Directory.CreateDirectory(empty);Check(Object.ReferenceEquals(DropImport.Read(old,new[]{empty},-1,()=>{}).Project,old),"Leerer Musikordner lässt die bisherige Bibliothek bestehen");
  int checks=0;bool cancelled=false;try{DropImport.Read(old,new[]{incoming},-1,()=>{if(++checks>3)throw new OperationCanceledException();});}catch(OperationCanceledException){cancelled=true;}Check(cancelled&&Storage.Bytes(old).SequenceEqual(snapshot),"Abgebrochener Import verändert die bisherige Bibliothek nicht");
  var maxed=old.WithFolders(Enumerable.Range(0,99).Select(i=>new BoxFolder{Name=i.ToString("D3")+" Alt",Theme="Alt"}).ToList());var replacement=DropImport.Read(maxed,new[]{a,b},-1,()=>{});Check(replacement.FilesAdded==2&&replacement.Project.Folders.Count==1,"99 alte Ordner blockieren einen kleinen neuen Import nicht");
  string large=Path.Combine(root,"080 Country");Directory.CreateDirectory(large);for(int i=0;i<100;i++)File.Copy(a,Path.Combine(large,i.ToString("D3")+".mp3"));var split=DropImport.Read(old,new[]{large},-1,()=>{});Check(split.Project.Folders.Select(f=>f.Songs.Count).SequenceEqual(new[]{99,1}),"100 neue Titel werden weiterhin auf 99 plus einen Folgetitel aufgeteilt");Check(split.Project.Folders.Select(f=>f.Name.Substring(0,3)).SequenceEqual(new[]{"080","081"}),"Quellnummer und Folgeordner innerhalb des neuen Imports bleiben korrekt");
  var many=Path.Combine(root,"Zu viele Themen");Directory.CreateDirectory(many);for(int i=0;i<100;i++){string d=Path.Combine(many,i.ToString("D3")+" Thema "+i);Directory.CreateDirectory(d);File.Copy(a,Path.Combine(d,"Titel.mp3"));}bool full=false;try{DropImport.Read(old,new[]{many},-1,()=>{});}catch(DropImportException ex){full=ex.Message.Contains("99");}Check(full&&Storage.Bytes(old).SequenceEqual(snapshot),"Mehr als 99 neue Themenordner werden ohne Verlust der bisherigen Bibliothek abgelehnt");
  Check(before.SequenceEqual(File.ReadAllBytes(input))&&Directory.GetFiles(incoming,"*.mp3").Length==2,"Originaldateien werden weder gelöscht noch verändert");Check(first.Report.Contains("Bisherige Bibliothek wird nach erfolgreichem Import ersetzt: 5 Ordner")&&first.Report.Contains("Neue Bibliothek: 1 von maximal 99 Ordnern"),"Importbericht beschreibt die neue Ersetzungsregel");
  Console.WriteLine("BESTANDEN: "+count+" Import-Ersetzungsprüfungen mit echten MP3-Dateien.");
 }
}
